Simpler with explicit recursion:

```js
  function buildTreeIndex(tree) {
    const parentOf = new Map(), nameOf = new Map(), pathOf = new Map();
    const subtreeNodeIds = new Map(), subtreeDeptIds = new Map();
    const deptIds = [];
    const visit = (node, parent, ancestors) => {
      parentOf.set(node.id, parent);
      nameOf.set(node.id, node.name);
      pathOf.set(node.id, ancestors.concat(node.name));
      const nodeIds = [node.id], depts = [];
      const isLeaf = !node.children || node.children.length === 0;
      if (isLeaf) { deptIds.push(node.id); depts.push(node.id); }
      else for (const c of node.children) {
        visit(c, node.id, ancestors.concat(node.name));
        subtreeNodeIds.get(c.id).forEach(id => nodeIds.push(id));
        subtreeDeptIds.get(c.id).forEach(id => depts.push(id));
      }
      subtreeNodeIds.set(node.id, nodeIds);
      subtreeDeptIds.set(node.id, depts);
    };
    tree.forEach(root => visit(root, null, []));
    return { parentOf, nameOf, pathOf, subtreeNodeIds, subtreeDeptIds, deptIds };
  }
```

