Batch ops:

```js
  // op = { type:"status"|"move"|"delete", ids:[...], value? , deptId? }
  // returns { entities(next Map), affectedIds, skippedIds, record }
  function applyBatch(entities, op) {
    const ids = op.ids.filter(id => entities.has(id)); // snapshot intersection with reality
    const before = new Map();
    const next = new Map(entities);
    const affected = [];
    let skipped = [];
    if (op.type === "status") {
      for (const id of ids) { const e = entities.get(id); before.set(id, snapshotOf(e));
        if (e.status !== op.value) { next.set(id, {...e, status: op.value}); affected.push(id); } else skipped.push(id); }
    } else if (op.type === "move") {
      for (const id of ids) { const e = entities.get(id); before.set(id, snapshotOf(e));
        if (e.deptId !== op.deptId) { next.set(id, {...e, deptId: op.deptId}); affected.push(id); } else skipped.push(id); }
    } else if (op.type === "delete") {
      for (const id of ids) { const e = entities.get(id); before.set(id, snapshotOf(e)); next.delete(id); affected.push(id); }
    }
    return { entities: next, affectedIds: affected, skippedIds: skipped, record: { op: {...op, ids}, before, at: Date.now() } };
  }
  function undoBatch(entities, record) {
    const next = new Map(entities);
    for (const [id, snap] of record.before) { next.set(id, { id, name: snap.name, model: snap.model, status: snap.status, deptId: snap.deptId }); }
    return next;
  }
  function validateMove(entities, ids) {
    const blocked = ids.filter(id => entities.get(id).status === "scrap");
    return { blockedIds: blocked, ok: blocked.length === 0 };
  }
```

